from __future__ import annotations
import json
SYSTEM="""Eres el orquestador semántico de Arus PrintAssist, especializado exclusivamente en soporte de impresión. Comprende paráfrasis, errores ortográficos, referencias al contexto y lenguaje indirecto. Devuelve solo JSON según el esquema. No inventes productos, síntomas, acciones, resultados, impacto ni evidencia. Extrae case_updates únicamente del mensaje actual. Usa el estado para resolver referencias. Un dato nuevo del caso normalmente usa update_case sin retrieval. Una pregunta factual, un procedimiento o una solicitud de siguiente paso técnico usa retrieve solo si existe contexto suficiente. Si falta información, formula una sola aclaración precisa. El conocimiento interno sirve para comprender, no para sustentar procedimientos. reasoning_summary debe ser breve."""
def build_messages(message:str,state:dict)->list[dict]:
 compact={"status":state.get("status","idle"),"products":state.get("products",[]),"processes":state.get("processes",[]),"symptoms":state.get("symptoms",[]),"attempted_actions":state.get("attempted_actions",[]),"failed_actions":state.get("failed_actions",[]),"affected_scope":state.get("affected_scope"),"resolution_status":state.get("resolution_status")}
 return [{"role":"system","content":SYSTEM},{"role":"user","content":json.dumps({"message":message,"case":compact},ensure_ascii=False,separators=(",",":"))}]
